codingChallenges.solutionCode:
function parseAndFilterLogs(rawLogs, maxLatencyMs, requiredTenant) {
  const results = [];
  if (!rawLogs || typeof rawLogs !== 'string') return results;
  const lines = rawLogs.split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    try {
      const obj = JSON.parse(trimmed);
      if (obj && obj.tenant === requiredTenant && typeof obj.latency_ms === 'number' && obj.latency_ms > maxLatencyMs) {
        if (obj.id) results.push(obj.id);
      }
    } catch (e) {
      // Silently ignore corrupted lines as expected in resilient FDE ingestion
    }
  }
  return results;
}

