codingChallenges.solutionCode:
function calculateBackoffDelays(attempts, baseMs, maxCapMs, factor = 0.5) {
  const delays = [];
  for (let i = 0; i < attempts; i++) {
    const exponential = baseMs * Math.pow(2, i);
    const capped = Math.min(maxCapMs, exponential);
    delays.push(Math.floor(capped * factor));
  }
  return delays;
}
